import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Initialize axios instance with auth token
  const api = axios.create({
    baseURL: API_URL,
    withCredentials: true,  // This is important for sending cookies with requests
    headers: {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
  });

  // Add request interceptor to add auth token to requests
  api.interceptors.request.use(
    (config) => {
      const token = localStorage.getItem('access_token');
      if (token) {
        config.headers['Authorization'] = `Bearer ${token}`;
      }
      return config;
    },
    (error) => {
      return Promise.reject(error);
    }
  );

  // Add response interceptor to handle token refresh
  api.interceptors.response.use(
    (response) => response,
    async (error) => {
      const originalRequest = error.config;

      // If error is 401 and we haven't tried to refresh yet
      if (error.response.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;

        try {
          const refreshToken = localStorage.getItem('refresh_token');
          if (!refreshToken) {
            // No refresh token, log out
            logout();
            return Promise.reject(error);
          }

          // Try to refresh the token
          const response = await axios.post(`${API_URL}/auth/refresh-token`, {
            refresh_token: refreshToken
          });

          const { access_token, refresh_token } = response.data;

          // Update tokens in localStorage
          localStorage.setItem('access_token', access_token);
          if (refresh_token) {
            localStorage.setItem('refresh_token', refresh_token);
          }

          // Update the authorization header
          originalRequest.headers['Authorization'] = `Bearer ${access_token}`;

          // Retry the original request
          return api(originalRequest);
        } catch (err) {
          // Refresh token failed, log out
          logout();
          return Promise.reject(err);
        }
      }

      return Promise.reject(error);
    }
  );

  // Check if user is authenticated on initial load
  const checkAuth = useCallback(async () => {
    try {
      const token = localStorage.getItem('access_token');
      if (!token) {
        setIsLoading(false);
        return;
      }

      // Set the token in the headers
      api.defaults.headers.common['Authorization'] = `Bearer ${token}`;

      // Add a small delay to prevent rate limiting
      await new Promise(resolve => setTimeout(resolve, 100));

      // Verify token and get user data
      const response = await api.get('/auth/me', {
        validateStatus: function (status) {
          return status < 500; // Resolve only if the status code is less than 500
        }
      });

      if (response.status === 200) {
        setUser(response.data);
      } else {
        // If we get an error, clear the tokens
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
        setUser(null);
      }
    } catch (err) {
      console.error('Authentication check failed:', err);
      // Only clear tokens if it's not a network error
      if (err.response) {
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
        setUser(null);
      }
    } finally {
      setIsLoading(false);
    }
  }, [api]);

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  const login = async (email, password) => {
    try {
      setError(null);
      // Clear any previous tokens to ensure a clean state
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');

      // Create form data for the login request
      const formData = new URLSearchParams();
      formData.append('username', email);
      formData.append('password', password);
      formData.append('grant_type', 'password');

      console.log('Sending login request to:', `${API_URL}/auth/token`);

      // Make the login request with credentials
      const response = await axios({
        method: 'post',
        url: `${API_URL}/auth/token`,
        data: formData.toString(),
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Accept': 'application/json',
        },
        withCredentials: true,
        validateStatus: (status) => status < 500, // Don't throw for 4xx errors
        xsrfCookieName: 'csrftoken',
        xsrfHeaderName: 'X-CSRFToken',
      });

      console.log('Login response:', response);

      if (response.status === 200 && response.data && response.data.access_token) {
        const { access_token, refresh_token, user } = response.data;

        // Store tokens
        localStorage.setItem('access_token', access_token);
        if (refresh_token) {
          localStorage.setItem('refresh_token', refresh_token);
        }

        // Set the default Authorization header for all future requests
        api.defaults.headers.common['Authorization'] = `Bearer ${access_token}`;

        // If user data is already in the response, use it
        if (user) {
          console.log('Using user data from login response:', user);
          setUser(user);
          return user;
        }

        try {
          // Fallback: Try to get user data from /auth/me
          console.log('Fetching user data from /auth/me...');
          const userResponse = await api.get('/auth/me', {
            headers: {
              'Accept': 'application/json',
            },
            withCredentials: true,
            validateStatus: (status) => status < 500
          });

          console.log('User data response:', userResponse);

          if (userResponse.data) {
            setUser(userResponse.data);
            return userResponse.data;
          } else {
            throw new Error('No user data received from /auth/me');
          }
        } catch (userDataError) {
          console.error('Error fetching user data:', userDataError);
          // If we have the token but couldn't fetch user data, still consider it a successful login
          // The user can refresh the page to try fetching the user data again
          return { email, isAuthenticated: true };
        }
      } else {
        // Handle non-200 responses
        throw new Error(response.data?.detail || 'Login failed');
      }

    } catch (error) {
      console.error('Login error:', error);

      let errorMessage = 'Login failed. Please try again.';

      if (error.response) {
        // The request was made and the server responded with a status code
        console.error('Error response data:', error.response.data);
        console.error('Error status:', error.response.status);
        console.error('Error headers:', error.response.headers);

        if (error.response.status === 400) {
          errorMessage = 'Invalid email or password. Please try again.';
        } else if (error.response.status === 401) {
          errorMessage = 'Authentication failed. Please log in again.';
        } else if (error.response.status === 403) {
          errorMessage = 'Account is inactive. Please contact support.';
        } else if (error.response.data && error.response.data.detail) {
          errorMessage = error.response.data.detail;
        } else if (error.response.data) {
          errorMessage = JSON.stringify(error.response.data);
        }
      } else if (error.request) {
        // The request was made but no response was received
        console.error('No response received:', error.request);
        errorMessage = 'Unable to connect to the server. Please check your connection and try again.';
      } else {
        // Something happened in setting up the request
        console.error('Error setting up request:', error.message);
        errorMessage = `Error: ${error.message}`;
      }

      // Clear tokens on error
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');
      setUser(null);
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const logout = () => {
    // Clear tokens and user data
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    setUser(null);

    // Redirect to login page
    navigate('/login');
  };

  const register = async (userData) => {
    try {
      setError(null);
      const response = await api.post('/auth/register', userData);

      // Auto-login after registration
      if (userData.password) {
        await login(userData.email, userData.password);
      }

      return response.data;
    } catch (err) {
      console.error('Registration error:', err);
      const errorMessage = err.response?.data?.detail || 'Registration failed. Please try again.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const value = {
    user,
    isAuthenticated: !!user,
    isLoading,
    error,
    setError, // Expose setError to allow components to clear errors
    login,
    logout,
    register,
    api, // Export the configured axios instance
  };

  return (
    <AuthContext.Provider value={value}>
      {!isLoading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
